window.HOEREN_TESTS[16] = {"id":"garten-und-pflanzen","name":"Garten und Pflanzen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Garten-Freunde, der Frühling beginnt. Im April können Sie schon Salat und Radieschen säen, aber Tomaten nur unter Glas — der Frost kann sie noch zerstören. Die richtige Zeit für Tomaten draußen ist Mitte Mai. Für Karotten sind beide Monate gut. Ihr Garten dankt es Ihnen.","gender":"f","q":"Wann darf man Tomaten draußen pflanzen?","opts":["Mitte Mai.","Im April.","Im Sommer."],"correct":0},{"transcript":"Hallo Maria, hier ist Tom vom Gartencenter. Ihre Bestellung — die zwei Apfelbäume — ist angekommen. Aber bitte abholen, wir liefern keine Bäume mehr. Die Bäume sind etwa 1 Meter 80 hoch, passen aber in ein normales Auto, wenn die Rückbank umgeklappt ist. Wir helfen beim Einpacken. Bis morgen!","gender":"m","q":"Was muss Maria tun?","opts":["Auf die Lieferung warten.","Die Bäume selbst abholen.","Die Bestellung stornieren."],"correct":1},{"transcript":"Achtung im Stadtpark: Die Rosen-Ausstellung ist verschoben. Statt diesem Wochenende findet sie erst nächsten Samstag statt — wegen schlechter Wetter-Vorhersage. Die Karten gelten dann automatisch für den neuen Termin. Wer das Geld zurück will, kann das an der Kasse machen, bis Donnerstag. Vielen Dank!","gender":"f","q":"Wann ist die Rosen-Ausstellung jetzt?","opts":["Dieses Wochenende.","In zwei Wochen.","Nächsten Samstag."],"correct":2},{"transcript":"Hi Anna, hier ist Lisa. Ich habe heute Morgen die Blumen für deinen Balkon gekauft — Geranien in Rot und Lavendel in Lila. Petunien wollte ich auch, aber die waren ausverkauft. Vielleicht nächste Woche. Ich bringe sie heute Abend vorbei, gegen 19 Uhr. Bis später! Danke dir!","gender":"f","q":"Welche Pflanzen sind ausverkauft?","opts":["Geranien.","Petunien.","Lavendel."],"correct":1},{"transcript":"Liebe Hörer, jetzt Tipps für den Sommer-Garten. Im Juli und August bei großer Hitze müssen Sie täglich gießen, am besten früh am Morgen oder spät am Abend. Mittags gießen ist schlecht — das Wasser verdunstet zu schnell und die Pflanzen verbrennen. Den ganzen Tag nass zu halten ist auch falsch. Also nur morgens oder abends, dann bleiben die Pflanzen gesund.","gender":"m","q":"Wann ist die beste Zeit zum Gießen?","opts":["Mittags.","Den ganzen Tag.","Morgens oder abends."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Anna und Markus. Sie planen die Gartenarbeit für die ganze Woche. Sie hören den Text einmal. Was wird wann gemacht? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Der Garten sieht diese Woche ziemlich wild aus."},{"speaker":"Markus","gender":"m","text":"Dann brauchen wir einen klaren Plan. An einem Nachmittag ist das zu viel für uns."},{"speaker":"Anna","gender":"f","text":"Das Gras mähen wir am Montag. Die Wiese hinter dem Haus ist viel zu lang."},{"speaker":"Markus","gender":"m","text":"Sollen wir vorher auch Dünger auf die Beete streuen?"},{"speaker":"Anna","gender":"f","text":"Nein. Dünger streuen wir nicht. Die Erde ist allein schon gut genug."},{"speaker":"Markus","gender":"m","text":"Die durstigen Blumen an der Mauer gieße ich am Dienstag."},{"speaker":"Anna","gender":"f","text":"Die Blumen sind ganz trocken. Danach sehen sie wieder frisch aus."},{"speaker":"Markus","gender":"m","text":"Die Hecke schneide ich am Mittwoch. Sie wächst schon weit über den Zaun hinaus."},{"speaker":"Anna","gender":"f","text":"Danach ist sie wieder schön gerade. Für die langen Reihen haben wir auch Zeit."},{"speaker":"Markus","gender":"m","text":"Unkraut zwischen den Reihen jäten wir am Donnerstag. Das geht nur bei trockenem Boden."},{"speaker":"Anna","gender":"f","text":"Das Unkraut zieht man besser mit der ganzen Wurzel heraus."},{"speaker":"Markus","gender":"m","text":"Wollen wir das Beet vor dem Haus noch umgraben?"},{"speaker":"Anna","gender":"f","text":"Nein. Das Beet graben wir nicht um. Der Boden soll so bleiben."},{"speaker":"Markus","gender":"m","text":"Was pflanzen wir dann noch an die sonnige Wand?"},{"speaker":"Anna","gender":"f","text":"Tomaten pflanzen wir am Samstag. Die Setzlinge stehen schon bereit."},{"speaker":"Markus","gender":"m","text":"Einverstanden. Ich lege den Zettel in den Schuppen."}],"options":[{"letter":"a","text":"Dünger streuen"},{"letter":"b","text":"Blumen gießen"},{"letter":"c","text":"Bäume schneiden"},{"letter":"d","text":"Garten genießen"},{"letter":"e","text":"Gras mähen"},{"letter":"f","text":"Hecke schneiden"},{"letter":"g","text":"Tomaten pflanzen"},{"letter":"h","text":"Unkraut jäten"},{"letter":"i","text":"Beet umgraben"}],"items":[{"person":"Montag","correct":"e"},{"person":"Dienstag","correct":"b"},{"person":"Mittwoch","correct":"f"},{"person":"Donnerstag","correct":"h"},{"person":"Samstag","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäuferin","gender":"f","text":"Guten Tag, was suchen Sie?"},{"speaker":"Kunde","gender":"m","text":"Eine schöne Pflanze fürs Wohnzimmer — etwas Grünes, kein Blühendes bitte."},{"speaker":"Verkäuferin","gender":"f","text":"Wie viel Licht haben Sie dort? Das ist wichtig für die Wahl."},{"speaker":"Kunde","gender":"m","text":"Wenig. Nur ein Fenster nach Norden, also dunkel."},{"speaker":"Verkäuferin","gender":"f","text":"Dann empfehle ich Ihnen eine Glücksfeder oder einen Bogenhanf. Beide brauchen wenig Licht."},{"speaker":"Kunde","gender":"m","text":"Die Glücksfeder ist hübsch, aber Bogenhanf ist mir lieber. Den nehme ich."}],"q":"Welche Pflanze kauft der Kunde?","opts":["Bogenhanf.","Eine blühende Pflanze.","Glücksfeder."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, mein Salat ist gelb geworden. Was ist falsch — Wasser oder Licht?"},{"speaker":"Gärtner","gender":"m","text":"Zu viel Wasser? Oder zu wenig? Auch zu wenig Licht macht Blätter gelb."},{"speaker":"Frau","gender":"f","text":"Licht hat er genug am Fenster. Ich gieße aber jeden Tag, morgens und abends."},{"speaker":"Gärtner","gender":"m","text":"Das ist zu viel Wasser. Alle zwei Tage reicht. Sonst werden die Wurzeln krank. Nicht zu wenig, sondern zu viel."},{"speaker":"Frau","gender":"f","text":"Verstehe, ich gieße ab jetzt seltener. Danke für den Tipp."}],"q":"Was war das Problem?","opts":["Zu wenig Wasser.","Zu viel Wasser.","Zu wenig Licht."],"correct":1},{"lines":[{"speaker":"Nachbar","gender":"m","text":"Guten Tag, Sie haben so einen schönen Apfelbaum! Selbst gepflanzt?"},{"speaker":"Nachbarin","gender":"f","text":"Ja, vor 8 Jahren — er war damals nur ein kleiner Setzling, nicht zwanzig Jahre alt."},{"speaker":"Nachbar","gender":"m","text":"Und ich dachte, das ist 20 Jahre alt, fast wie ein hundertjähriger Baum. Wie viele Äpfel trägt er jedes Jahr?"},{"speaker":"Nachbarin","gender":"f","text":"Etwa 100 Kilo, nicht 100 Jahre alt. Ich gebe viele Äpfel an Nachbarn weg."},{"speaker":"Nachbar","gender":"m","text":"Wahnsinn, nur 8 Jahre und so viele Äpfel. Respekt!"}],"q":"Wie alt ist der Baum?","opts":["100 Jahre.","20 Jahre.","8 Jahre."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Schatz, wir brauchen einen neuen Rasenmäher. Der alte ist kaputt."},{"speaker":"Sohn","gender":"m","text":"Elektrisch oder benzin? Oder kaufen wir gar keinen und leihen einen?"},{"speaker":"Vater","gender":"m","text":"Benzin ist stärker, aber laut. Ein elektrischer ist günstiger im Betrieb. Leihen ist umständlich."},{"speaker":"Sohn","gender":"m","text":"Lass uns elektrisch nehmen. Wir haben sowieso Strom genug, und er ist leiser."},{"speaker":"Vater","gender":"m","text":"Einverstanden, dann den elektrischen Mäher. Kein Benzin."}],"q":"Welchen Mäher kaufen sie?","opts":["Elektrischen Mäher.","Benzin-Mäher.","Sie kaufen keinen."],"correct":0},{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Guten Tag, möchten Sie Erde kaufen für den Garten?"},{"speaker":"Kundin","gender":"f","text":"Ja, für meinen Balkon. Welche haben Sie — Bio oder normal? Ohne Erde kaufe ich nicht."},{"speaker":"Mitarbeiterin","gender":"f","text":"Blumenerde ist normal und günstig. Bio-Erde ist besser für die Umwelt, kostet aber doppelt."},{"speaker":"Kundin","gender":"f","text":"Bio kostet zu viel für den kleinen Balkon, ich nehme normale Blumenerde."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gerne, eine Tüte normale Erde. Das reicht für den Balkon."}],"q":"Welche Erde kauft sie?","opts":["Bio-Erde.","Normale Blumenerde.","Sie kauft keine."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Müller, einer Gärtnerin in einem Park. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Müller, Sie sind Gärtnerin im Stadtpark seit 15 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Müller","gender":"f","text":"Ich wuchs auf dem Land auf, bei meiner Großmutter. Sie hatte einen großen Gemüsegarten, und ich war immer dabei. Mit 18 wollte ich eigentlich Tierärztin werden, aber die Ausbildung war nichts für mich. So bin ich Gärtnerin geworden — und das passt."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie täglich im Park?"},{"speaker":"Müller","gender":"f","text":"Im Frühling pflanzen wir tausende neue Blumen. Im Sommer gießen und pflegen. Im Herbst Laub harken und Bäume schneiden. Im Winter haben wir auch zu tun — Werkzeug reparieren, Pflanzen im Gewächshaus pflegen, planen für das nächste Jahr."},{"speaker":"Reporter","gender":"m","text":"Was ist Ihre Lieblingsblume?"},{"speaker":"Müller","gender":"f","text":"Rosen mag ich, aber sie sind viel Arbeit. Sonnenblumen sind robust und schön. Aber meine Liebe sind die kleinen Frühlings-Blumen — Schneeglöckchen und Krokusse. Sie kommen, wenn alles noch grau ist."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"Müller","gender":"f","text":"Das Wetter. Bei zu wenig Regen brauchen wir extra Bewässerung. Bei Sturm sind viele Pflanzen kaputt. Klimawandel macht alles schwerer — wir müssen Pflanzen wählen, die heißen Sommer aushalten."},{"speaker":"Reporter","gender":"m","text":"Haben Sie einen Garten zu Hause?"},{"speaker":"Müller","gender":"f","text":"Einen kleinen Balkon nur. Im Park arbeite ich mit Hunderten von Quadratmetern, da brauche ich zu Hause keine große Pflanzenwelt. Mein Balkon hat Kräuter und ein paar Tomaten — das reicht."}],"items":[{"q":"Frau Müller wuchs in der Stadt auf.","correct":"nein"},{"q":"Sie hat eine Lehre als Tierärztin gemacht.","correct":"nein"},{"q":"Im Winter hat sie keine Arbeit.","correct":"nein"},{"q":"Sonnenblumen sind ihre absolute Lieblingsblume.","correct":"nein"},{"q":"Sie hat zu Hause einen Balkon mit Pflanzen.","correct":"ja"}]}]};
